class MedianFinder {
  constructor() {
    this.sorted = [];
  }
  addNum(num) {
    let lo = 0, hi = this.sorted.length;     // binary search for where num belongs
    while (lo < hi) {
      const mid = (lo + hi) >> 1;
      if (this.sorted[mid] < num) lo = mid + 1; else hi = mid;
    }
    this.sorted.splice(lo, 0, num);          // insert: shifts up to n values
  }
  findMedian() {
    const s = this.sorted, mid = Math.floor(s.length / 2);
    return s.length % 2 ? s[mid] : (s[mid - 1] + s[mid]) / 2;
  }
}

