class MedianFinder {
    private final List<Integer> sorted = new ArrayList<>();

    void addNum(int num) {
        int lo = 0, hi = sorted.size();          // binary search for where num belongs
        while (lo < hi) {
            int mid = (lo + hi) >>> 1;
            if (sorted.get(mid) < num) lo = mid + 1; else hi = mid;
        }
        sorted.add(lo, num);                     // insert: shifts up to n values
    }

    double findMedian() {
        int mid = sorted.size() / 2;
        return sorted.size() % 2 == 1 ? sorted.get(mid) : (sorted.get(mid - 1) + sorted.get(mid)) / 2.0;
    }
}

