class MedianFinder {
  constructor() {
    this.low = new Heap((a, b) => b - a);    // max-heap: the smaller half
    this.high = new Heap();                  // min-heap: the larger half
  }
  addNum(num) {
    this.low.push(num);                      // 1. join the smaller half...
    this.high.push(this.low.pop());          // 2. ...whose largest moves to the larger half
    if (this.high.size() > this.low.size()) this.low.push(this.high.pop());   // 3. low keeps the extra one
  }
  findMedian() {
    if (this.low.size() > this.high.size()) return this.low.peek();
    return (this.low.peek() + this.high.peek()) / 2;
  }
}

import heapq

class MedianFinder:
    def __init__(self):
        self.low = []                        # the smaller half, negated: a max-heap
        self.high = []                       # the larger half: a min-heap

    def addNum(self, num):
        heapq.heappush(self.low, -num)                        # 1. join the smaller half...
        heapq.heappush(self.high, -heapq.heappop(self.low))   # 2. ...whose largest moves up
        if len(self.high) > len(self.low):                    # 3. low keeps the extra one
            heapq.heappush(self.low, -heapq.heappop(self.high))

    def findMedian(self):
        if len(self.low) > len(self.high):
            return float(-self.low[0])
        return (-self.low[0] + self.high[0]) / 2

class MedianFinder {
    private final PriorityQueue<Integer> low = new PriorityQueue<>(Collections.reverseOrder());   // smaller half
    private final PriorityQueue<Integer> high = new PriorityQueue<>();                           // larger half

    void addNum(int num) {
        low.offer(num);                      // 1. join the smaller half...
        high.offer(low.poll());              // 2. ...whose largest moves to the larger half
        if (high.size() > low.size()) low.offer(high.poll());   // 3. low keeps the extra one
    }

    double findMedian() {
        if (low.size() > high.size()) return low.peek();
        return (low.peek() + high.peek()) / 2.0;
    }
}

class MedianFinder {
    priority_queue<int> low;                                   // the smaller half: a max-heap
    priority_queue<int, vector<int>, greater<int>> high;       // the larger half: a min-heap

public:
    void addNum(int num) {
        low.push(num);                       // 1. join the smaller half...
        high.push(low.top());                // 2. ...whose largest moves to the larger half
        low.pop();
        if (high.size() > low.size()) {      // 3. low keeps the extra one
            low.push(high.top());
            high.pop();
        }
    }

    double findMedian() {
        if (low.size() > high.size()) return low.top();
        return (low.top() + (double)high.top()) / 2;
    }
};
